// @include-start buildMessage.js
// Собирает текст сообщения о вакансии для Telegram.
// Нода Telegram отправляет его с Parse Mode = HTML: заголовок выделяем жирным,
// а весь текст со стороны (Djinni, позже Gemini) экранируем, чтобы символы
// < > & не ломали разметку и Telegram не отклонил сообщение.
const TIME_ZONE = 'Europe/Kyiv';
const MAX_SUMMARY_LENGTH = 300;

function buildMessage(vacancy, { now = new Date() } = {}) {
  const lines = [`🆕 <b>${escapeHtml(vacancy.title)}</b>`];

  // Строки от ИИ появятся на этапе 5; пока полей нет, нет и строк
  if (vacancy.ai_score) lines.push(`🎯 Підходить: ${vacancy.ai_score}/10`);
  const ai = readAiSummary(vacancy.ai_summary);
  const stack = Array.isArray(ai.stack) ? ai.stack.join(', ') : ai.stack;
  if (stack) lines.push(`🧩 ${escapeHtml(stack)}`);
  if (ai.english) lines.push(`🇬🇧 ${escapeHtml(ai.english)}`);
  if (ai.salary) lines.push(`💰 ${escapeHtml(ai.salary)}`);
  // Сначала обрезаем, потом экранируем: иначе можно разрезать &amp; посередине
  if (ai.summary) lines.push(`📝 ${escapeHtml(truncate(ai.summary, MAX_SUMMARY_LENGTH))}`);

  const publishedAt = new Date(vacancy.published_at);
  if (vacancy.published_at && !Number.isNaN(publishedAt.getTime())) {
    lines.push(`🕒 ${formatPublishedAt(publishedAt, now)}`);
  }
  lines.push(`🔗 ${escapeHtml(vacancy.url)}`);

  return lines.join('\n');
}

// В режиме HTML Telegram требует заменить три символа.
// & меняем первым, иначе готовые &lt; превратятся в &amp;lt;
function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// ai_summary — колонка JSONB: из Postgres приходит объектом, строку JSON тоже понимаем.
// Битые данные не роняют отправку: просто не будет строк от ИИ
function readAiSummary(value) {
  let data = value;
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch {
      return {};
    }
  }
  return data && typeof data === 'object' ? data : {};
}

// Array.from режет по символам, а не по половинкам эмодзи (в JS они из двух частей)
function truncate(text, maxLength) {
  const chars = Array.from(String(text).trim());
  if (chars.length <= maxLength) return chars.join('');
  return `${chars.slice(0, maxLength - 1).join('').trimEnd()}…`;
}

// «сьогодні, 14:01» / «вчора, 23:30» / «13.01, 14:46» — по времени Киева
function formatPublishedAt(date, now) {
  const published = kyivParts(date);
  const today = kyivParts(now);
  const time = `${published.hour}:${published.minute}`;
  const daysAgo = dayNumber(today) - dayNumber(published);

  if (daysAgo === 0) return `сьогодні, ${time}`;
  if (daysAgo === 1) return `вчора, ${time}`;
  return `${published.day}.${published.month}, ${time}`;
}

// Части даты по часовому поясу Киева: { year, month, day, hour, minute }.
// Летнее и зимнее время Intl учитывает сам
function kyivParts(date) {
  const formatter = new Intl.DateTimeFormat('en-GB', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  });
  return Object.fromEntries(formatter.formatToParts(date).map(({ type, value }) => [type, value]));
}

// Номер календарного дня: разница номеров = сколько дней прошло
function dayNumber({ year, month, day }) {
  return Date.UTC(Number(year), Number(month) - 1, Number(day)) / (24 * 60 * 60 * 1000);
}
// @include-end

// --- «клей»: подключаем функцию к данным n8n ---
return $input.all().map((item, index) => ({
  json: { ...item.json, text: buildMessage(item.json) },
  pairedItem: index,
}));

// @include-start buildAiPrompt.js
// Собирает промпт для Gemini: профиль кандидата, правила оценки и текст вакансии.
// Личных данных (имя, контакты, город, ссылки) здесь нет и быть не должно:
// на бесплатном тарифе Google может использовать запросы для обучения, а файл лежит в git.
const MAX_DESCRIPTION_LENGTH = 3000; // длинные описания режем, чтобы не тратить токены

const PROFILE = `Junior Frontend Developer (React + TypeScript). No commercial experience yet.
About 1.5 years of frontend practice, 1 year of it with React and TypeScript.
Built and deployed two fullstack portfolio apps (a personal finance app and an online store).
Main skills: React 18, TypeScript, Redux Toolkit, RTK Query, React Router, Formik + Yup,
SCSS (Modules, BEM), responsive layout from 320px, Figma, Vite, i18next.
Also: Node.js, Express, NestJS, PostgreSQL, Prisma, JWT auth, Docker, Jest.
Learning now: n8n, workflow automation, AI APIs.
English: B1 (Intermediate).
Wants: remote work, salary from $500 per month.`;

const SCORING = `9-10: junior or trainee role with React + TypeScript (Next.js is fine too),
or JavaScript fullstack with React + Node.js/NestJS; remote; English B1 or lower;
salary from $500 or not stated.
7-8: good fit with small gaps: Vue or another modern frontend stack; English B2;
up to 1 year of commercial experience required.
4-6: partial fit: Angular, React Native or a mostly backend role; 2+ years required;
hybrid or office only.
1-3: does not fit: middle or senior level; not JavaScript (.NET, Java, PHP, Python and so on);
not a developer role; salary clearly below $500.
Add 1 point (max 10) if the job involves n8n, workflow automation or AI integrations.`;

const OUTPUT_FORMAT = `Reply with JSON only, without markdown and without any other text. Fields:
- "score": integer from 1 to 10
- "stack": array of up to 6 key technologies from the vacancy
- "english": required English level as a string, or null if not stated
- "salary": salary as written in the vacancy, or null if not stated
- "summary": one short sentence in Ukrainian about the company and the tasks`;

function buildAiPrompt(vacancy, { profile = PROFILE } = {}) {
  const title = String(vacancy?.title ?? '').trim();
  const description = truncate(vacancy?.description, MAX_DESCRIPTION_LENGTH) || '(no description)';

  return [
    'You help a junior developer choose job vacancies. Rate how well the vacancy fits the candidate.',
    '',
    'CANDIDATE:',
    profile,
    '',
    'HOW TO SCORE (1-10):',
    SCORING,
    '',
    'VACANCY:',
    `Title: ${title}`,
    description,
    '',
    OUTPUT_FORMAT,
  ].join('\n');
}

// Array.from режет по символам, а не по половинкам эмодзи
function truncate(text, maxLength) {
  const chars = Array.from(String(text ?? '').trim());
  if (chars.length <= maxLength) return chars.join('');
  return `${chars.slice(0, maxLength - 1).join('').trimEnd()}…`;
}
// @include-end

// --- «клей»: промпт для каждой вакансии ---
return $input.all().map((item, index) => ({
  json: { prompt: buildAiPrompt(item.json) },
  pairedItem: index,
}));

// @include-start parseAiResponse.js
// Разбирает ответ Gemini. Модели иногда оборачивают JSON в ```json, пишут текст
// до или после, путают типы полей. Функция достаёт JSON-объект, проверяет и чистит поля.
// При любом сбое возвращает null: тогда вакансия уйдёт в Telegram без блока с оценкой.
const MAX_STACK_ITEMS = 6;
const MAX_FIELD_LENGTH = 100;
const MAX_SUMMARY_LENGTH = 300;

// Так модели иногда пишут «нет данных» вместо null
const EMPTY_VALUES = new Set([
  '', 'null', 'none', 'n/a', 'na', '-', 'unknown', 'not stated', 'not specified',
  'не вказано', 'не указано',
]);

function parseAiResponse(text) {
  const data = extractJsonObject(text);
  if (!data) return null;

  // Без оценки весь ответ бесполезен
  const rawScore = typeof data.score === 'number' ? data.score : Number.parseFloat(data.score);
  if (!Number.isFinite(rawScore)) return null;

  return {
    score: Math.min(Math.max(Math.round(rawScore), 1), 10),
    stack: cleanStack(data.stack),
    english: cleanText(data.english, MAX_FIELD_LENGTH),
    salary: cleanText(data.salary, MAX_FIELD_LENGTH),
    summary: cleanText(data.summary, MAX_SUMMARY_LENGTH),
  };
}

// Сначала ищем блок ```json ... ```, потом берём текст от первой { до последней }
function extractJsonObject(text) {
  const raw = String(text ?? '');
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(raw);
  const candidate = fenced ? fenced[1] : raw;

  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end <= start) return null;

  try {
    const data = JSON.parse(candidate.slice(start, end + 1));
    return data && typeof data === 'object' && !Array.isArray(data) ? data : null;
  } catch {
    return null;
  }
}

// Стек: массив или строка через запятую → до 6 непустых уникальных названий
function cleanStack(value) {
  const items = Array.isArray(value) ? value : String(value ?? '').split(',');
  const result = [];
  for (const item of items) {
    const text = cleanText(item, MAX_FIELD_LENGTH);
    if (text && !result.includes(text)) result.push(text);
  }
  return result.slice(0, MAX_STACK_ITEMS);
}

// Строка или число → строка без лишних пробелов; «нет данных» и всё остальное → null
function cleanText(value, maxLength) {
  if (typeof value !== 'string' && typeof value !== 'number') return null;
  const text = String(value).replace(/\s+/g, ' ').trim();
  if (EMPTY_VALUES.has(text.toLowerCase())) return null;
  return truncate(text, maxLength);
}

function truncate(text, maxLength) {
  const chars = Array.from(text);
  if (chars.length <= maxLength) return text;
  return `${chars.slice(0, maxLength - 1).join('').trimEnd()}…`;
}
// @include-end

// --- «клей» (режим Run Once for Each Item) ---
// Цепочка LLM отдаёт только { text }, поэтому вакансию берём из Loop Over Items.
// Если Gemini упал, text не будет, parseAiResponse вернёт null — вакансия уйдёт без оценки
const vacancy = $('Loop Over Items').item.json;
const ai = parseAiResponse($json.text);

return { json: { id: vacancy.id, ai_score: ai?.score ?? null, ai_summary: ai } };
